"""`mac contacts` — generated by tools/gen_groups.py from local-mac's contacts__* handlers. Do not edit."""
from mac.groups._backend import call


def register(registry):
    def contacts_search_args(p):
        p.add_argument('name')
        p.add_argument('--include-email', action="store_true")

    @registry.verb("contacts", "search", mode="read",
                   desc='search contacts by name via Contacts.app', args=contacts_search_args)
    def contacts_search(ns):
        return call('contacts', 'search', name=ns.name, include_email=ns.include_email)
